INSERT INTO _migration_424_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_006' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Mansa''s school began a silent reading period every morning. At first the students grumbled, but within a term the library''s borrowing records had doubled and essays had grown longer and richer. "You cannot hear a book," the headmistress said, "until the noise stops." Soon parents asked how to start the habit at home." How often was the silent reading period held?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. once a week","B. every morning","C. every evening","D. once a term"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The opening sentence says the school "began a silent reading period every morning". Weekly, evening and termly periods are not mentioned.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_006' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
