INSERT INTO _migration_424_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_008' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Mansa''s school began a silent reading period every morning. At first the students grumbled, but within a term the library''s borrowing records had doubled and essays had grown longer and richer. "You cannot hear a book," the headmistress said, "until the noise stops." Soon parents asked how to start the habit at home." Which of the following does the passage give as evidence that the reading period succeeded?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The students stopped grumbling at home","B. The headmistress closed the library","C. The parents bought new books for the school","D. The library''s borrowing records had doubled"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The passage names two pieces of evidence: doubled borrowing records and richer essays. Only the first appears among the options.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_008' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_424_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_009' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Mansa''s school began a silent reading period every morning. At first the students grumbled, but within a term the library''s borrowing records had doubled and essays had grown longer and richer. "You cannot hear a book," the headmistress said, "until the noise stops." Soon parents asked how to start the habit at home." The headmistress''s words "You cannot hear a book until the noise stops" mean that' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. reading requires quiet and full attention","B. books make a noise when they are read aloud","C. students should stop reading noisy books","D. the library should be soundproofed"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The saying is figurative: "hearing" a book means absorbing it and "noise" means distraction, so reading needs quiet attention.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_009' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_424_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_cmp_mcq_010' AND NOT (q.topic_id IS 'topic_wassce_english_comprehension' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Mansa''s school began a silent reading period every morning. At first the students grumbled, but within a term the library''s borrowing records had doubled and essays had grown longer and richer. "You cannot hear a book," the headmistress said, "until the noise stops." Soon parents asked how to start the habit at home." The word "grumbled" as used in the passage means' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. rejoiced openly","B. complained in a quiet, discontented way","C. refused to obey","D. read aloud"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Their later benefit shows the first reaction was muted discontent, not refusal: "grumbled" means complained in a low, discontented way.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_cmp_mcq_010' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
